import 'package:material_ui/material_ui.dart';
import 'package:flutter_application/main.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:mockito/annotations.dart';
import 'package:mockito/mockito.dart';
import 'package:openapi/api.dart';
import 'package:provider/provider.dart';

// The mocks are generated by: dart run build_runner build
@GenerateNiceMocks([MockSpec<HealthApi>()])
import 'widget_test.mocks.dart';

Widget _appWith(HealthApi api) {
  return Provider<HealthApi>(
    create: (_) => api,
    child: const HandballApp(),
  );
}

void main() {
  testWidgets('shows that the server is reachable', (tester) async {
    final api = MockHealthApi();
    when(api.getHealth()).thenAnswer((_) async => Health(status: 'ok'));

    await tester.pumpWidget(_appWith(api));
    await tester.pumpAndSettle();

    expect(find.text('Server erreichbar'), findsOneWidget);
  });

  testWidgets('shows that the server is not reachable', (tester) async {
    final api = MockHealthApi();
    when(api.getHealth()).thenThrow(ApiException(503, 'down'));

    await tester.pumpWidget(_appWith(api));
    await tester.pumpAndSettle();

    expect(find.text('Server nicht erreichbar'), findsOneWidget);
  });
}
